import React, { useEffect, useState, useRef } from "react";
import styled, { keyframes, css } from "styled-components";
import { Divider } from "antd";
import Flower from "../assets/flower1.png";

const Wrapper = styled.div`
  padding-top: 42px;
  margin: 0 auto;
  width: 90%;
`;

const Title = styled.p`
  font-size: 2.2rem;
  color: var(--title-color);
  font-weight: bold;
  opacity: 0.85;
  margin-bottom: 0;
  text-align: center;
  font-family: "mom_to_daughter";
`;

const fadeIn = keyframes`
  from { opacity: 0; transform: translateY(10px); }
  to { opacity: 1; transform: translateY(0); }
`;

const Line = styled.p`
  font-size: 0.9rem;
  line-height: 1.75;
  opacity: ${({ visible }) => (visible ? 1 : 0)};
  animation: ${({ visible }) => (visible ? fadeIn : "none")} 0.8s forwards;
  margin-bottom: 16px;
  text-align: center;
`;

const GroomBrideWrapper = styled.div`
  display: flex;
  justify-content: center;
`;

const typing = keyframes`
  from { width: 0; }
  to { width: 100%; }
`;

const GroomBride = styled.p`
  font-size: 2.0rem;
  font-family: "mom_to_daughter";
  font-weight: bold;
  opacity: 0.9;
  margin-top: 12px;
  white-space: nowrap;
  overflow: hidden;
  text-align: center;
  border-right: ${({ showCursor }) => (showCursor ? "2px solid rgba(80,60,50,0.8)" : "none")};
  width: 100%;

  ${({ startTyping }) =>
    startTyping
      ? css`
          animation: ${typing} 5s steps(30, end) forwards;
        `
      : css`
          width: 0;
        `}
`;

const Image = styled.img`
  display: block;
  margin: 0 auto;
  width: 1.375rem;
  padding-bottom: 42px;
`;

const Greeting = () => {
  const lines = [
    "생각해보면, 자기가 나한테 해준 게 참 많다",
    "손도 자기가 먼저 잡자고 해줬고,",
    "우리 첫 여행도 자기가 먼저 가자고 했었지",
    "그 모든 순간이 내겐 큰 행복이야",
    "이제는 내가, 자기에게 먼저 말하고 싶어."
  ];

  const [visibleLines, setVisibleLines] = useState(Array(lines.length).fill(false));
  const [startTyping, setStartTyping] = useState(false);
  const [showCursor, setShowCursor] = useState(true);
  const lineRefs = useRef([]);

  useEffect(() => {
    lineRefs.current = lineRefs.current.slice(0, lines.length);

    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            const index = Number(entry.target.dataset.index);

            if (index === 0) {
              // 첫 줄 등장
              setVisibleLines((prev) => {
                const newState = [...prev];
                newState[index] = true;
                return newState;
              });

              // 첫 줄이 뜨면 순차적으로 다음 줄 등장
              for (let i = 1; i < lines.length; i++) {
                setTimeout(() => {
                  setVisibleLines((prev) => {
                    const newState = [...prev];
                    newState[i] = true;
                    return newState;
                  });

                  // 마지막 줄일 때 GroomBride 타이핑 2초 뒤 시작
                  if (i === lines.length - 1) {
                    setTimeout(() => {
                      setStartTyping(true);
                      setTimeout(() => setShowCursor(false), 3000); // 타이핑 끝나면 커서 숨김
                    }, 2000);
                  }
                }, i * 2000); // 이전 줄 기준 2초 간격
              }
            }

            observer.unobserve(entry.target);
          }
        });
      },
      { threshold: 0.3 }
    );

    if (lineRefs.current[0]) observer.observe(lineRefs.current[0]);

    return () => observer.disconnect();
  }, []);

  return (
    <Wrapper>
      <Divider style={{ marginTop: 32, marginBottom: 32 }} plain>
        <Title data-aos="fade-up">나랑 데이트 할래?</Title>
      </Divider>
      <Image data-aos="fade-up" src={Flower} />
      {lines.map((line, idx) => (
        <Line
          key={idx}
          ref={(el) => (lineRefs.current[idx] = el)}
          data-index={idx}
          visible={visibleLines[idx]}
        >
          {line}
        </Line>
      ))}

      <GroomBrideWrapper>
        <GroomBride startTyping={startTyping} showCursor={showCursor}>
          희승아, 나랑 데이트하러 가자!
        </GroomBride>
      </GroomBrideWrapper>
    </Wrapper>
  );
};

export default Greeting;